50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	const CURSE_SURCHARGE_PERCENT = 50;
53	const HIGH_ENCHANTMENT_LEVEL = 5;
54	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
55	
56	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	  moonstone: 25,
63	};
64	
65	/** Modifiers are expressed as an amount to add, never as a factor to multiply
66	 *  by, so that they stay additive against their base and so that the integer
67	 *  numerator keeps float artifacts out of the final rounding
68	 *  (100 * 1.1 === 110.000…1, but (100 * 10) / 100 === 10 exactly). */
69	const percentOf = (amount: number, percent: number): number =>
70	  (amount * percent) / 100;
71	
72	/** Rounds up — premiums round in the MHPCO's favour. */
73	const roundPremium = (amount: number): number => Math.ceil(amount);
74	
75	const COMPONENT_BLOCK_SIZE = 3;
76	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
77	
78	const COMPONENT_TYPES = ["rune", "moonstone"];
79	
80	const isComponent = (item: Item): boolean =>
81	  COMPONENT_TYPES.includes(item.type);
82	
83	const itemBasePremium = (item: Item): number =>
84	  BASE_PREMIUM_BY_TYPE[item.type];
85	
86	const countByType = (items: Item[]): Map<string, number> => {
87	  const counts = new Map<string, number>();
88	  for (const item of items) {
89	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
90	  }
91	  return counts;
92	};
93	
94	/** A block is exactly three alike components, priced as a unit rather than
95	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
96	const componentGroupBasePremium = ([type, count]: [string, number]): number =>
97	  count === COMPONENT_BLOCK_SIZE
98	    ? COMPONENT_BLOCK_BASE_PREMIUM
99	    : count * BASE_PREMIUM_BY_TYPE[type];
100	
101	const sum = (amounts: number[]): number =>
102	  amounts.reduce((total, amount) => total + amount, 0);
103	
104	const policyBasePremium = (items: Item[]): number => {
105	  const mainItems = items.filter((item) => !isComponent(item));
106	  const componentGroups = [...countByType(items.filter(isComponent))];
107	
108	  return (
109	    sum(mainItems.map(itemBasePremium)) +
110	    sum(componentGroups.map(componentGroupBasePremium))
111	  );
112	};
113	
114	/** Item-scoped surcharges apply to the affected item's own base premium,
115	 *  not to the policy total. They stack. */
116	const itemSurchargeAmount = (item: Item): number => {
117	  const base = itemBasePremium(item);
118	  const curse = item.cursed ? percentOf(base, CURSE_SURCHARGE_PERCENT) : 0;
119	  const enchantment =
120	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
121	      ? percentOf(base, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
122	      : 0;
123	  return curse + enchantment;
124	};
125	
126	const quote = (items: Item[]): QuoteResult => {
127	  const basePremium = policyBasePremium(items);
128	  // Every modifier is an amount added to the base premium, not a factor
129	  // compounded onto a running total: item-scoped modifiers take a percentage
130	  // of their own item's base premium, policy-wide ones take a percentage of
131	  // the policy base premium.
132	  const modifierAmounts = [
133	    ...items.map(itemSurchargeAmount),
134	    percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT),
135	  ];
136	  // The processing fee is added last, after all percentage modifiers.
137	  const premium = basePremium + sum(modifierAmounts) + PROCESSING_FEE;
138	  return { premium: roundPremium(premium) };
139	};
140	
141	const runStep = (step: Step): StepResult => {
142	  if (step.op === "quote") return quote(step.items);
143	  throw new Error(`Unsupported step: ${step.op}`);
144	};
145	
146	export const runScenario = (scenario: Scenario): ScenarioResult => {
147	  const results = scenario.steps.map(runStep);
148	  return { results };
149	};
