interface SurchargeRule {
  appliesTo: (item: Item) => boolean;
  percent: number;
}

/** Every item-scoped surcharge, as a rule that either applies to an item or
 *  does not. Applicable rules stack. */
const ITEM_SURCHARGE_RULES: SurchargeRule[] = [
  {
    appliesTo: (item) => item.cursed === true,
    percent: CURSE_SURCHARGE_PERCENT,
  },
  {
    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
  },
];

/** Item-scoped surcharges apply to the affected item's own base premium,
 *  not to the policy total. */
const itemSurchargeAmount = (item: Item): number =>
  sum(
    ITEM_SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).map((rule) =>
      percentOf(itemBasePremium(item), rule.percent),
    ),
  );
